/**
 * @brief Select the typed IR opcode for an analyzed binary expression.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "In C:\Users\wwwho\Downloads\IFJ26\knowledge, you have details about
// this project. Everything should be implemented, except a portion of lowering.
// Finish its implementation. Match the style how optimizer was written, split
// code into meaningful commits. Before committing each commit stop and wait for
// my confirmation."
// Changes: Select an IR instruction for a checked binary operator.
static IrInstructionType binary_instruction(Ctx* ctx,
                                            AstNodeType kind,
                                            IrType result_type) {
  switch (kind) {
    case AST_NODE_ADD:
      // The source uses + for both numeric addition and string concatenation.
      return result_type == IR_STRING ? IR_INST_CONCAT : IR_INST_ADD;
    case AST_NODE_SUB:
      return IR_INST_SUB;
    case AST_NODE_MUL:
      return IR_INST_MUL;
    case AST_NODE_DIV:
      return result_type == IR_INT ? IR_INST_IDIV : IR_INST_DIV;
    case AST_NODE_EQ:
      return IR_INST_EQ;
    case AST_NODE_NEQ:
      return IR_INST_NE;
    case AST_NODE_LT:
      return IR_INST_LT;
    case AST_NODE_LE:
      return IR_INST_LE;
    case AST_NODE_GT:
      return IR_INST_GT;
    case AST_NODE_GE:
      return IR_INST_GE;
    default:
      THROW(E_INTERNAL_ERROR, "Unexpected binary expression kind: %d", kind);
      return IR_INST_ADD;  // Unreachable
  }
}

/**
 * @brief Lower both operands of a binary expression and emit the corresponding
 * operation.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "In C:\Users\wwwho\Downloads\IFJ26\knowledge, you have details about
// this project. Everything should be implemented, except a portion of lowering.
// Finish its implementation. Match the style how optimizer was written, split
// code into meaningful commits. Before committing each commit stop and wait for
// my confirmation."
// Changes: Lower binary operands in order and stop when a path returns.
static IrOperand lower_binary(Ctx* ctx,
                              IrFunctionId function_id,
                              IrBlockId* block_id,
                              AstNode* node) {
  AstNode* left_node = ast_node_child(ctx, node, AST_BINARY_LEFT);
  AstNode* right_node = ast_node_child(ctx, node, AST_BINARY_RIGHT);

  // Lower the left operand first so side effects occur in source order.
  IrOperand left = lower_expression(ctx, function_id, block_id, left_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  IrOperand right = lower_expression(ctx, function_id, block_id, right_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  IrType type = ast_to_ir_data_type(ctx, ast_node_get_data_type(node));
  IrInstructionType instruction =
      binary_instruction(ctx, ast_node_get_type(node), type);

  return add_binary(ctx, function_id, *block_id, instruction, type, left,
                    right);
}

/**
 * @brief Lower a unary expression and return its IR operand.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "In C:\Users\wwwho\Downloads\IFJ26\knowledge, you have details about
// this project. Everything should be implemented, except a portion of lowering.
// Finish its implementation. Match the style how optimizer was written, split
// code into meaningful commits. Before committing each commit stop and wait for
// my confirmation."
// Changes: Lower unary operators on paths that continue after the operand.
static IrOperand lower_unary(Ctx* ctx,
                             IrFunctionId function_id,
                             IrBlockId* block_id,
                             AstNode* node) {
  AstNode* operand_node = ast_node_child(ctx, node, AST_UNARY_OPERAND);
  IrOperand operand =
      lower_expression(ctx, function_id, block_id, operand_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  switch (ast_node_get_type(node)) {
    case AST_NODE_NOT:
      return add_unary(ctx, function_id, *block_id, IR_INST_NOT, IR_BOOL,
                       operand);
    case AST_NODE_INT_TO_DOUBLE:
      return add_unary(ctx, function_id, *block_id, IR_INST_INT2DOUBLE,
                       IR_DOUBLE, operand);
    case AST_NODE_NEG:
      // Multiplication by -1.0 also flips the sign of a floating-point zero.
      if (ast_node_get_data_type(node) == AST_DATA_TYPE_DOUBLE)
        return add_binary(ctx, function_id, *block_id, IR_INST_MUL, IR_DOUBLE,
                          double_operand(-1.0), operand);
      return add_binary(ctx, function_id, *block_id, IR_INST_SUB, IR_INT,
                        int_operand(0), operand);
    default:
      THROW(E_INTERNAL_ERROR, "Unexpected unary expression");
      return unit_operand();  // Unreachable
  }
}

/**
 * @brief Load the resolved lexical binding into an IR value.
 */
