// Changes: Emit a call and represent a Unit result with an immediate operand.
static IrOperand add_call(Ctx* ctx,
                          IrFunctionId function_id,
                          IrBlockId block_id,
                          IrInstruction instruction) {
  IrValueId value = ir_add_instruction(ctx, function_id, block_id, instruction);

  return value == IR_INVALID_ID ? unit_operand() : value_operand(value);
}

/**
 * @brief Convert a typed operand to the string representation used by source
 * expressions.
 *
 * @param ctx Compiler context owning the IR.
 * @param fid Function receiving the instruction.
 * @param bid Block receiving the instruction.
 * @param type Static type of the operand.
 * @param operand Already evaluated argument.
 * @return String operand used by the lowered expression.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "In C:\Users\wwwho\Downloads\IFJ26\knowledge, you have details about
// this project. Everything should be implemented, except a portion of lowering.
