    return add_unary(ctx, function_id, *block_id, IR_INST_FLOOR, IR_DOUBLE,
                     receiver);

  const SymtableData* symbol = ast_node_get_symbol(node);
  IrType type = ast_to_ir_data_type(ctx, ast_node_get_data_type(receiver_node));
