/**
 * @brief Evaluate interpolation parts in source order and build the string
 * result.
 *
 * @param ctx Compiler context owning the IR.
 * @param function_id Function receiving the lowered expression.
 * @param[in,out] block_id Current block, invalidated if evaluation terminates.
 * @param node Interpolation expression to lower.
 * @return String operand, or Unit if evaluation terminates.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "In C:\Users\wwwho\Downloads\IFJ26\knowledge, you have details about
// this project. Everything should be implemented, except a portion of lowering.
// Finish its implementation. Match the style how optimizer was written, split
// code into meaningful commits. Before committing each commit stop and wait for
// my confirmation."
// Changes: Concatenate interpolation parts until a part ends the path.
static IrOperand lower_interpolation(Ctx* ctx,
                                     IrFunctionId function_id,
                                     IrBlockId* block_id,
                                     AstNode* node) {
  IrOperand result = string_operand("");
  size_t count = ast_node_get_child_count(node);

  for (size_t i = 0; i < count; i++) {
    AstNode* part = ast_node_child(ctx, node, i);
    IrOperand value = lower_expression(ctx, function_id, block_id, part);
    if (*block_id == IR_INVALID_ID)
      return unit_operand();

    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Ok, implement all, remove things made redundant by this change"
    // Changes: Use typed conversion operations for interpolation parts.
    value = lower_to_string(
        ctx, function_id, *block_id,
        ast_to_ir_data_type(ctx, ast_node_get_data_type(part)), value);

    // Reuse the first part directly. The initial empty string covers s"".
    result = i == 0 ? value
                    : add_binary(ctx, function_id, *block_id, IR_INST_CONCAT,
                                 IR_STRING, result, value);
  }

  return result;
}

/**
 * @brief Lower an analyzed AST expression into IR and return its resulting
 * operand.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "In C:\Users\wwwho\Downloads\IFJ26\knowledge, you have details about
// this project. Everything should be implemented, except a portion of lowering.
// Finish its implementation. Match the style how optimizer was written, split
// code into meaningful commits. Before committing each commit stop and wait for
// my confirmation."
// Changes: Dispatch conditional and short-circuit expressions to CFG lowering.
IrOperand lower_expression(Ctx* ctx,
                           IrFunctionId function_id,
                           IrBlockId* block_id,
                           AstNode* node) {
  switch (ast_node_get_type(node)) {
    case AST_NODE_INT_LIT:
      return int_operand(ast_node_get_value(node).int_value);
    case AST_NODE_DOUBLE_LIT:
      return double_operand(ast_node_get_value(node).double_value);
    case AST_NODE_STRING_LIT:
      // IR instructions and terminators copy the borrowed AST string.
      return string_operand((IrString)ast_node_get_value(node).string_value);
    case AST_NODE_BOOL_LIT:
      return bool_operand(ast_node_get_value(node).boolean_value);
    case AST_NODE_UNIT_LIT:
      return unit_operand();
    case AST_NODE_IDENT:
      return lower_identifier(ctx, function_id, *block_id, node);

    case AST_NODE_ADD:
    case AST_NODE_SUB:
    case AST_NODE_MUL:
    case AST_NODE_DIV:
    case AST_NODE_EQ:
    case AST_NODE_NEQ:
    case AST_NODE_LT:
    case AST_NODE_LE:
    case AST_NODE_GT:
    case AST_NODE_GE:
      return lower_binary(ctx, function_id, block_id, node);

    case AST_NODE_NOT:
    case AST_NODE_NEG:
    case AST_NODE_INT_TO_DOUBLE:
      return lower_unary(ctx, function_id, block_id, node);

    case AST_NODE_CALL:
      return lower_call(ctx, function_id, block_id, node);
    case AST_NODE_MEMBER:
      return lower_member(ctx, function_id, block_id, node);
    case AST_NODE_INTERP_STRING:
      return lower_interpolation(ctx, function_id, block_id, node);

    case AST_NODE_IF:
      return lower_if(ctx, function_id, block_id, node);
    case AST_NODE_AND:
    case AST_NODE_OR:
      return lower_logical(ctx, function_id, block_id, node);

    default:
      THROW(E_INTERNAL_ERROR, "Unexpected expression kind: %d",
            ast_node_get_type(node));
      return unit_operand();  // Unreachable
  }
}
